import{_ as t,o,c as e,Q as a}from"./chunks/framework.b67c47e6.js";const n="/assets/account-page.835fd5d3.svg",m=JSON.parse('{"title":"Account Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/account/index.md","filePath":"guide/account/index.md","lastUpdated":1793281423000}'),i={name:"guide/account/index.md"},s=a('<h1 id="account-settings" tabindex="-1">Account Settings <a class="header-anchor" href="#account-settings" aria-label="Permalink to &quot;Account Settings&quot;">​</a></h1><p>The Account page shows who you are and where you work, and lets you set up how you sign in, your language and the notifications you get. Open it from the account button at the top of the left menu: <strong>Account</strong>.</p><p><img src="'+n+'" alt="The Account page"></p><ol><li>Your profile: username, email, alias and language.</li><li>Your workplace: company, role and station.</li><li>Two-factor authentication and Google or Microsoft sign-in.</li><li>Which messages you get, and the emails about them.</li><li>The applications you connected, such as Claude.</li></ol><p>On a wide screen the page has two columns, as above. On a smaller screen, and on a phone, the same cards follow each other in one column, in the order of the numbers.</p><p>Every setting on this page is saved as soon as you change it. There is no <strong>Save</strong> button.</p><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h2><ul><li><strong>Username</strong> — Your login name.</li><li><strong>Email</strong> — The email of your account, or <em>No email</em>.</li><li><strong>Alias</strong> — How you are named on the factory floor. Shown only when it differs from your username.</li><li><strong>Language</strong> — The language of the interface. Shown only if multilanguage is enabled for your account.</li></ul><h2 id="workplace" tabindex="-1">Workplace <a class="header-anchor" href="#workplace" aria-label="Permalink to &quot;Workplace&quot;">​</a></h2><ul><li><strong>Company</strong> — The company your account belongs to.</li><li><strong>Role</strong> — What your account may do: company administrator, company manager, production user or external viewer.</li><li><strong>Production station</strong> — The line and station you work at, or <em>No station</em>. Change it from the account menu in the left menu.</li></ul><h2 id="sign-in-and-security" tabindex="-1">Sign-in and security <a class="header-anchor" href="#sign-in-and-security" aria-label="Permalink to &quot;Sign-in and security&quot;">​</a></h2><h3 id="two-factor-authentication" tabindex="-1">Two-factor authentication <a class="header-anchor" href="#two-factor-authentication" aria-label="Permalink to &quot;Two-factor authentication&quot;">​</a></h3><p>With two-factor authentication on, signing in asks for a code from an authenticator app on your phone, as well as your password. The row says whether it is <strong>On</strong> or <strong>Off</strong>.</p><p>To turn it on:</p><ol><li>Click <strong>Set up</strong>.</li><li>Scan the QR code with your authenticator app (Google Authenticator, Authy, etc.).</li><li>Enter the 6-digit code the app shows and click <strong>Turn on</strong>.</li></ol><p>To turn it off, click <strong>Turn off</strong>, then <strong>Turn off</strong> again to confirm.</p><h3 id="linked-accounts" tabindex="-1">Linked accounts <a class="header-anchor" href="#linked-accounts" aria-label="Permalink to &quot;Linked accounts&quot;">​</a></h3><p>Link a Google or Microsoft account to sign in faster. Use the Google sign-in button, or <strong>Link</strong> next to Microsoft, and <strong>Unlink</strong> to remove a link. Linking replaces your account email with the provider&#39;s. A provider that is not set up shows <em>Not available</em>.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>The <strong>bell</strong> at the top of the left menu, next to the QR button, counts the notifications you have not read. Click it to see them, newest first. On a phone the menu is closed most of the time, so its toggle at the top left shows a dot while something is unread.</p><p>You get a notification when:</p><ul><li><strong>A task you launched finishes or fails</strong>: a report, the automatic drawings, <em>Update designs</em>, a project download, a transfer or copy, a company backup. One notification per run, with the details inside: click <strong>Show details</strong> to read the IFC warnings grouped by file, the drawings that failed, or the error.</li><li><strong>Duplicate files are deleted</strong> after one of your uploads. The deleted files are listed in the details.</li><li><strong>A colleague reports an issue</strong> and picks you under <strong>Notify colleagues</strong>.</li><li><strong>produuz.it is updated</strong>, if <strong>Produuz.it updates</strong> is on.</li></ul><p>Click a notification to mark it read and open what it is about: the report, the design, the project&#39;s files, the issue or the download. <strong>Mark all as read</strong> clears the count. Notifications are kept for 30 days.</p><p>When a new notification arrives while you work, a message at the bottom right says how many there are, with <strong>Open</strong> to see them. The messages at the bottom right that answer what you just did (<em>Saved</em>, <em>Could not save</em>) are not kept: they are gone after a few seconds.</p><p>The <strong>Notifications</strong> card of this page has three settings:</p><ul><li><strong>Errors in automatic tasks</strong> — failures of tasks nobody launched by hand, such as automations, go to the admins and managers who have this on. A task you launch always notifies you.</li><li><strong>Produuz.it updates</strong> — a notification when a new version of produuz.it is out.</li><li><strong>Also send by email</strong> — each notification is also sent to your email address.</li></ul><h2 id="connected-apps" tabindex="-1">Connected Apps <a class="header-anchor" href="#connected-apps" aria-label="Permalink to &quot;Connected Apps&quot;">​</a></h2><p><strong>Connected apps</strong> lists the applications you have allowed to read your produuz.it data, such as an AI assistant connected through <a href="/guide/mcp/">MCP</a>. For each one you see what it may access and when it was last used; an app marked <em>not reviewed</em> has not been checked by produuz.it. Click <strong>Disconnect</strong> to revoke its access.</p>',28),r=[s];function l(c,h,u,d,g,p){return o(),e("div",null,r)}const y=t(i,[["render",l]]);export{m as __pageData,y as default};
